class Solution {
public:
    long long matrixSumQueries(int n, vector<vector<int>>& queries) {
        long long sum = 0;
        vector<bool> seenRow(n, false), seenCol(n, false);
        int seenRows = 0, seenCols = 0;
        for (int i = (int)queries.size() - 1; i >= 0; i--) {
            int type = queries[i][0];
            int index = queries[i][1];
            int val = queries[i][2];
            if (type == 0) {
                if (!seenRow[index]) {
                    sum += (long long)val * (n - seenCols);
                    seenRow[index] = true;
                    seenRows++;
                }
            } else {
                if (!seenCol[index]) {
                    sum += (long long)val * (n - seenRows);
                    seenCol[index] = true;
                    seenCols++;
                }
            }
        }
        return sum;
    }
};
